    verificador: Verificador = Depends(get_verificador),
    reloj: Callable[[], datetime] = Depends(get_reloj),
    ajustes: Settings = Depends(get_settings),
):
    uid = usuario["id"]
    llegada = reloj()   # cuándo llegó la solicitud al servidor
    ahora = llegada     # la hora de la marcación: la del servidor… salvo en una marcación sin conexión (paso 4)

    try:
        # 1) Reintento: la app reenvía la misma marcación (mismo id) tras un corte de red.
        existente = await sb.marcacion_fila(str(datos.id))
        if existente:
            if existente["usuario_id"] != uid:
                raise HTTPException(409, "Ese identificador de marcación ya está en uso")
            return JSONResponse(
                {"marcacion": _resumen(existente), "anomalias": [], "reintento": True}, status_code=200
            )

        # 2) Ubicación simulada: Android avisa cuando la posición viene de una app de GPS falso. No se registra.
        if datos.ubicacion_simulada:
            await _registrar_anomalia(
                sb, uid, "ubicacion_simulada", "El celular informó que la ubicación es simulada (GPS falso)", None
            )
            raise HTTPException(
                403,
                "Detectamos que la ubicación de tu celular es simulada. Desactiva la app de ubicación falsa e inténtalo de nuevo",
            )

        # 3) Dispositivo: si la cuenta ya tiene uno vinculado, la app debe marcar desde ese.
        vinculado = usuario.get("dispositivo_id")
        if datos.origen == "app" and vinculado and datos.dispositivo_id and datos.dispositivo_id != vinculado:
            raise HTTPException(403, "Este dispositivo no es el vinculado a tu cuenta")
        # … 4) sede, 4a) precisión, 4b) hora, reloj y firma sin conexión, 5) secuencia del día

# 6) Rostro.
# Los umbrales del reconocimiento los fija el administrador en el panel (ya vienen en `cfg`).
try:
    verif = await verificador.verificar(usuario, datos.selfie_b64, Criterios.desde(cfg, ajustes))
except HTTPException as e:
    # Sin conexión la persona ya no está para repetir la foto: si la selfie no se puede analizar (oscura,
    # borrosa…), la marcación se guarda sin verificar y una persona la revisa. Lo demás (sin rostro registrado,
    # sin selfie, servicio caído) se rechaza igual que siempre.
    if not (datos.sin_conexion and e.status_code == 422 and datos.selfie_b64):
        raise
    verif = ResultadoVerificacion("pendiente", None, str(e.detail))
if verif.estado == "fallida" and not datos.sin_conexion:
    inicio_hoy, _ = reglas.limites_del_dia(ahora)
    previos = await sb.contar_verificaciones_fallidas(uid, _iso(inicio_hoy))
    await _registrar_anomalia(
        sb, uid, "verificacion_fallida", verif.motivo or "El rostro no coincide", None, previos + 1
    )
    # `codigo` e `intento` permiten a la app mostrar la pantalla de «verificación no superada»
    # sin tener que adivinar por el texto del mensaje.
    return JSONResponse(
        status_code=422,
        content={
            "detail": "No pudimos verificar tu rostro. Intenta de nuevo con buena luz y de frente"
            + (f" ({verif.motivo})" if verif.motivo else ""),
            "codigo": "rostro_no_verificado",
            "intento": previos + 1,
        },
    )

def distancia_m(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    """Distancia en metros entre dos puntos (fórmula de haversine)."""
    r = 6_371_000
    f1, f2 = radians(lat1), radians(lat2)
    a = sin((f2 - f1) / 2) ** 2 + cos(f1) * cos(f2) * sin(radians(lon2 - lon1) / 2) ** 2
    return 2 * r * asin(sqrt(a))


def evaluar_zona(lat: float, lon: float, sede: dict, bloques_activos: list[dict]) -> Zona:
    """Valida la ubicación contra los bloques activos de la sede o, si no hay, contra la sede."""
    if not bloques_activos:
        d = distancia_m(lat, lon, sede["latitud"], sede["longitud"])
        limite = sede["radio_metros"]
        if d <= limite:
            return Zona(True, None, f"A {d:.0f} m del centro de la sede (radio {limite} m)", sede.get("nombre"), d, limite, (sede["latitud"], sede["longitud"]))
        return Zona(False, None, f"A {d:.0f} m del centro de la sede; el radio permitido es {limite} m",
                    sede.get("nombre"), d, limite, (sede["latitud"], sede["longitud"]))

    medidos = [(distancia_m(lat, lon, b["latitud"], b["longitud"]), b) for b in bloques_activos]
    dentro = [(d, b) for d, b in medidos if d <= b["radio_metros"]]
    if dentro:
        d, b = min(dentro, key=lambda x: x[0])  # si los círculos se traslapan, el de centro más cercano
        return Zona(True, b["id"], f"A {d:.0f} m del centro de «{b['nombre']}» (radio {b['radio_metros']} m)",
                    b["nombre"], d, b["radio_metros"], (b["latitud"], b["longitud"]))
    d, b = min(medidos, key=lambda x: x[0] - x[1]["radio_metros"])  # el que queda más cerca de su borde
    return Zona(
        False, None,
        f"A {d:.0f} m del centro del bloque más cercano («{b['nombre']}»); su radio es {b['radio_metros']} m",
        b["nombre"], d, b["radio_metros"], (b["latitud"], b["longitud"]),
    )

class ClienteGemini:
    """Igual que `ClienteIA` pero con la API de Gemini (Google AI Studio). Misma interfaz: `evaluar` y `aclose`."""

    URL = "https://generativelanguage.googleapis.com/v1beta/models/{modelo}:generateContent"

    def __init__(self, api_key: str, modelo: str, timeout: float = 20, transport: httpx.AsyncBaseTransport | None = None):
        self._modelo = modelo
        # La llave va en una cabecera (no en la URL) para que no quede en registros ni en mensajes de error.
        self._headers = {"x-goog-api-key": api_key, "content-type": "application/json"}
        self._http = httpx.AsyncClient(timeout=timeout, transport=transport)

    async def aclose(self) -> None:
        await self._http.aclose()

    async def evaluar(self, caso: dict, mensajes: list[dict], ultima: bool) -> Evaluacion:
        turnos = [{"role": "model" if m["role"] == "assistant" else "user", "parts": [{"text": m["content"]}]}
                  for m in armar_mensajes(mensajes)]
        if not turnos:
            raise IAError("No hay mensajes que evaluar")
        cuerpo = {
            "systemInstruction": {"parts": [{"text": instrucciones(caso, ultima, formato_json=True)}]},
            "contents": turnos,
            "generationConfig": {"temperature": 0.2, "maxOutputTokens": 2000, "responseMimeType": "application/json"},
        }
        try:
            resp = await self._http.post(self.URL.format(modelo=self._modelo), headers=self._headers, json=cuerpo)
        except httpx.HTTPError as e:
            raise IAError(f"No se pudo contactar a la IA: {type(e).__name__}") from e
        if resp.status_code >= 400:
            raise IAError(f"La IA respondió con error {resp.status_code}", status=resp.status_code)
        try:
            texto = resp.json()["candidates"][0]["content"]["parts"][0]["text"]
        except (ValueError, KeyError, IndexError, TypeError) as e:
            # Sin candidatos suele significar que Google bloqueó la petición por sus filtros de seguridad.
            raise IAError("La respuesta de la IA no tiene el formato esperado") from e
        return leer_evaluacion(_json_de(texto))

export function clasificar(e: unknown): Clasificacion {
  if (e instanceof ApiError) {
    if (e.status === 0) return { accion: 'reintentar', motivo: 'sin_red', mensaje: e.message }
    if (e.status === 401 || e.codigo === 'cuenta_inhabilitada') return { accion: 'reintentar', motivo: 'sesion', mensaje: e.message }
    if (e.status >= 500 || e.status === 408 || e.status === 429) return { accion: 'reintentar', motivo: 'servidor', mensaje: e.message }
    return { accion: 'descartar', mensaje: e.message }
  }
  // Un error que no conocemos no debe costar una marcación: se conserva y se vuelve a intentar.
  return { accion: 'reintentar', motivo: 'servidor', mensaje: e instanceof Error ? e.message : String(e) }
}

